    # Initialize a dictionary to store elements and their counts
    element_counts = {}

    # Iterate through list1 to count the occurrences of each element
    for element in list1:
        if element in element_counts:
            element_counts[element] += 1
        else:
            element_counts[element] = 1

    # Iterate through list2 to find similar elements
    similar_elements = []
    for element in list2:
        if element in element_counts and element_counts[element] > 1:
            similar_elements.append(element)

    return similar_elements

