def number_of_ways(n):
    # Initialize the board with all 0s
    board = [[0]*2 for _ in range(n)]

    # Define the valid moves
    moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Initialize the count
    count = 1

    # Fill the board with dominoes
    while any(sum(row) == 2 for row in board):
        for i in range(n):
            for j in range(n):
                if board[i][j] == 0:
                    for move in moves:
                        x, y = i + move[0], j + move[1]
                        if 0 <= x < n and 0 <= y < n and board[x][y] == 0:
                            board[x][y] = 1
                            board[i][j] = 0
                            count += 1
                            break

    return count
```

