def differ_at_one_bit_position(a, b):
    if a == b:
        return False
    i = 0
    while i < len(bin(a)[2:]) and i < len(bin(b)[2:]):
        if bin(a)[2:].index('1' + '0' * (len(bin(a)) - i - 1) + '1') != bin(b)[2:].index('1' + '0' * (len(bin(b)) - i - 1) + '1'):
            return True
        i += 1
    return False
```

