def most_common_words(dictionary, n):
    """
    Counts the most common words in a dictionary.

    Args:
    dictionary (dict): A dictionary of words and their frequencies.
    n (int): The number of most common words to return.

    Returns:
    dict: A dictionary with the most common words and their frequencies.
    """
    word_counts = {}
    for word, freq in dictionary.items():
        if word in word_counts:
            word_counts[word] += freq
        else:
            word_counts[word] = freq

    most_common = sorted(word_counts.items(), key=lambda x: x[1], reverse=True)[:n]
    return dict(most_common)

